import React from 'react';
import { useNavigate } from 'react-router-dom';
import './Home.css';

function Home() {
    const navigate = useNavigate();

    return (
        <div className="home-container">
            <section className="hero">
                <h1>Food Care</h1>
                <p>Conectando quem quer doar com quem precisa receber.</p>
                <div className="home-actions">
                    <button onClick={() => navigate('/login')} className="btn-primary">
                        Entrar no Painel
                    </button>
                    <button onClick={() => navigate('/cadastro')} className="btn-secondary">
                        Criar Conta
                    </button>
                </div>
            </section>

            <section className="features">
                <div className="feature-card">
                    <h3>Para Doadores</h3>
                    <p>Cadastre alimentos próximos à validade e ajude instituições locais.</p>
                </div>
                <div className="feature-card">
                    <h3>Para Receptores</h3>
                    <p>Encontre itens disponíveis e solicite doações de forma organizada.</p>
                </div>
            </section>
        </div>
    );
}

export default Home;
